shaderSource:
uniform float2 resolution;
uniform float tiltX;
uniform float tiltY;

half3 hsv2rgb(half3 c) {
  half4 K = half4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  half3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

half3 hueShift(half3 color, float shift) {
  float mx = max(color.r, max(color.g, color.b));
  float mn = min(color.r, min(color.g, color.b));
  float d = mx - mn;
  float h = 0.0;
  if (d > 0.0001) {
    if (mx == color.r) h = (color.g - color.b) / d + (color.g < color.b ? 6.0 : 0.0);
    else if (mx == color.g) h = (color.b - color.r) / d + 2.0;
    else h = (color.r - color.g) / d + 4.0;
    h /= 6.0;
  }
  float s = mx <= 0.0 ? 0.0 : d / mx;
  return hsv2rgb(half3(fract(h + shift), s, mx));
}

half4 main(float2 xy) {
  float2 uv = xy / resolution;
  float2 centered = uv - float2(0.5, 0.5);
  float light = 0.55 + 0.45 * (1.0 - length(centered + float2(tiltX, tiltY) * 0.18));
  half3 base = half3(0.72, 0.76, 0.82) * light;
  float shift = tiltX * 0.42 + tiltY * 0.28 + length(centered) * 0.35;
  half3 chrome = hueShift(base, shift);
  float rim = smoothstep(0.62, 0.28, length(centered));
  chrome = mix(chrome * 0.55, chrome, rim);
  return half4(chrome, 1.0);
}
